package com.medicore.notification.service; import com.medicore.notification.dto.*; import com.medicore.notification.entity.Notification; import com.medicore.notification.repository.NotificationRepository; import org.springframework.stereotype.Service; import java.util.Set; @Service public class NotificationService {private final NotificationRepository repository; public NotificationService(NotificationRepository repository){this.repository=repository;} public NotificationResponse create(NotificationRequest r){return response(repository.save(new Notification(r.userId(),r.message())));} public NotificationResponse find(Long id){return response(repository.findById(id).orElseThrow(()->new IllegalArgumentException("Notification not found")));} public NotificationResponse status(Long id,String s){if(!Set.of("PENDING","SENT","FAILED").contains(s))throw new IllegalArgumentException("Invalid status");Notification n=repository.findById(id).orElseThrow(()->new IllegalArgumentException("Notification not found"));n.setStatus(s);return response(repository.save(n));} private NotificationResponse response(Notification n){return new NotificationResponse(n.getId(),n.getUserId(),n.getMessage(),n.getStatus());}}
